operaciones.consulta:
query Cities($countryId: String!) {
  cities(country_id: $countryId) {
    edges {
      node {
        id
        name
        regions {
          regionId
          regionName
          __typename
        }
        settings {
          hasFoodSales
          hasPresales
          __typename
        }
        timezone
        cinemas {
          id
          regionId
          vistaId
          type
          name
          cityId
          lat
          lng
          alias
          businessType
          experiences {
            icon
            name
            __typename
          }
          settings {
            requireContiguousSeating
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
